import streamlit as st
import os
import sys

# Import the lightweight emotion detector
from src.lightweight_emotion import LightweightEmotionDetector
from src.response_generator import ResponseGenerator

# Page configuration
st.set_page_config(
    page_title="Teacher Assistant Bot (Lightweight)",
    page_icon="🤖",
    layout="wide"
)

# Create models directory if it doesn't exist
os.makedirs("models", exist_ok=True)

# Initialize session state
if "messages" not in st.session_state:
    st.session_state.messages = []
if "emotion_detector" not in st.session_state:
    st.session_state.emotion_detector = LightweightEmotionDetector()
if "response_generator" not in st.session_state:
    st.session_state.response_generator = ResponseGenerator()

# Custom CSS
st.markdown("""
<style>
    .stChat {
        padding: 20px;
        border-radius: 10px;
        margin: 10px 0;
    }
    .user-message {
        background-color: #e6f3ff;
        text-align: right;
    }
    .assistant-message {
        background-color: #f0f2f6;
    }
    .emotion-label {
        font-size: 0.8em;
        color: #666;
        margin-top: 5px;
    }
    .stButton button {
        width: 100%;
    }
</style>
""", unsafe_allow_html=True)

# Sidebar for model selection and information
with st.sidebar:
    st.title("ℹ️ Configuration")
    
    # Model selection
    st.header("LLM Model Selection")
    
    # Check for existing models
    model_files = []
    if os.path.exists("models"):
        for file in os.listdir("models"):
            if file.endswith((".gguf", ".ggml", ".bin")):
                model_files.append(file)
    
    # Display model selection options
    if model_files:
        selected_model = st.selectbox(
            "Select a model:",
            options=model_files,
            help="Select a GGUF or GGML model to use for generating responses"
        )
        
        if st.button("Load Selected Model"):
            with st.spinner("Loading model... This may take a moment"):
                model_path = os.path.join("models", selected_model)
                if st.session_state.response_generator.set_model(model_path):
                    st.success(f"Successfully loaded model: {selected_model}")
                else:
                    st.error("Failed to load model. Check logs for details.")
    
    # Model upload
    st.header("Upload New Model")
    uploaded_file = st.file_uploader("Choose a GGUF/GGML model file", type=["gguf", "ggml", "bin"])
    
    if uploaded_file is not None:
        with st.spinner("Uploading model... This may take a moment"):
            # Save the uploaded model
            model_path = os.path.join("models", uploaded_file.name)
            with open(model_path, "wb") as f:
                f.write(uploaded_file.getbuffer())
            
            st.success(f"Model uploaded: {uploaded_file.name}")
            
            # Option to load the uploaded model
            if st.button("Load Uploaded Model"):
                if st.session_state.response_generator.set_model(model_path):
                    st.success(f"Successfully loaded model: {uploaded_file.name}")
                else:
                    st.error("Failed to load model. Check logs for details.")
    
    # Status display
    st.header("Current Status")
    if st.session_state.response_generator.llm:
        st.success("✅ LLM is loaded and active")
        st.info(f"Model: {os.path.basename(st.session_state.response_generator.model_path)}")
    else:
        st.warning("⚠️ Using fallback mode (no LLM)")
        st.info("Responses are based on predefined templates and lightweight emotion detection.")
    
    st.success("✅ Using lightweight emotion detection (NLTK)")
    
    # Information about the application
    st.header("About")
    st.markdown("""
    ### Features
    - Lightweight emotion detection with NLTK
    - Teaching advice based on detected emotions
    - LLM integration for personalized responses (optional)
    - Mobile-friendly interface
    - Fast startup and low resource usage
    
    ### Usage Tips
    - Be specific about classroom situations
    - Mention student behaviors and age groups
    - Ask for specific strategies or approaches
    """)
    
    # Example queries
    st.subheader("Example Queries")
    examples = [
        "My students seem disengaged during math lessons. What can I do?",
        "A student is showing signs of anxiety before tests. How can I help?",
        "The class becomes very excited and hard to manage after lunch. Any advice?",
        "Some students are struggling with group work. What strategies would you recommend?"
    ]
    
    for example in examples:
        if st.button(f"📝 {example[:40]}...", key=example):
            st.session_state.messages.append({"role": "user", "content": example})
            st.rerun()

# Main chat interface
st.title("👩‍🏫 Teacher Assistant Bot (Lightweight)")
st.markdown("""
Share your classroom situations and get personalized teaching advice!
The bot will analyze student emotions and provide actionable recommendations.

This lightweight version starts up faster and uses fewer resources.
""")

# Display chat messages
for message in st.session_state.messages:
    with st.container():
        if message["role"] == "user":
            st.markdown(f"**You:** {message['content']}")
        else:
            st.markdown(f"**Assistant:** {message['content']}")
            if "emotions" in message:
                emotions_text = ", ".join([
                    f"{emotion} ({score:.0%})"
                    for emotion, score in message["emotions"]
                    if score > 0.1
                ])
                if emotions_text:
                    st.markdown(f"*Detected emotions: {emotions_text}*")

# Chat input
if prompt := st.chat_input("Type your message here..."):
    # Add user message to chat history
    st.session_state.messages.append({"role": "user", "content": prompt})
    
    # Detect emotions
    emotions = st.session_state.emotion_detector.detect_emotions(prompt)
    
    # Generate response
    response = st.session_state.response_generator.generate_response(
        prompt=prompt,
        emotions=emotions,
        conversation_history=st.session_state.messages[:-1]  # Exclude the current message
    )
    
    # Add assistant response to chat history
    st.session_state.messages.append({
        "role": "assistant",
        "content": response,
        "emotions": emotions
    })
    
    # Rerun to update the display
    st.rerun()

# Footer
st.markdown("---")
st.markdown("""
Made with ❤️ using Streamlit and open-source models. LLM support powered by llama-cpp-python.
Lightweight mode uses NLTK for faster performance.
""")
